<?php
require_once __DIR__ . '/_friend_helpers.php';
try { $c=friends_connection(); if(!SessionHelper::isAuthenticated()){ApiResponse::unauthorized();exit;} $uid=SessionHelper::getUserId(); $type=$_GET['type']??'incoming'; $page=max(1,(int)($_GET['page']??1)); $limit=min(50,max(1,(int)($_GET['limit']??20))); $offset=($page-1)*$limit; $field=$type==='outgoing'?'sender_id':'receiver_id'; $other=$type==='outgoing'?'receiver_id':'sender_id'; $cnt=$c->prepare("SELECT COUNT(*) total FROM friend_requests WHERE $field=:uid AND status='pending'");$cnt->execute(['uid'=>$uid]);$total=(int)$cnt->fetch(PDO::FETCH_ASSOC)['total']; $s=$c->prepare("SELECT fr.id,fr.sender_id,fr.receiver_id,fr.status,fr.created_at,u.id uid,u.username,u.full_name,u.profile_photo,u.is_memorial FROM friend_requests fr JOIN users u ON u.id=fr.$other WHERE fr.$field=:uid AND fr.status='pending' ORDER BY fr.created_at DESC LIMIT :limit OFFSET :offset"); $s->bindValue(':uid',$uid,PDO::PARAM_INT);$s->bindValue(':limit',$limit,PDO::PARAM_INT);$s->bindValue(':offset',$offset,PDO::PARAM_INT);$s->execute(); $rows=[]; foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r){$rows[]=['id'=>(int)$r['id'],'sender_id'=>(int)$r['sender_id'],'receiver_id'=>(int)$r['receiver_id'],'status'=>$r['status'],'created_at'=>$r['created_at'],'user'=>friends_safe_user(['id'=>$r['uid'],'username'=>$r['username'],'full_name'=>$r['full_name'],'profile_photo'=>$r['profile_photo'],'is_memorial'=>$r['is_memorial']])];} ApiResponse::success(['requests'=>$rows,'pagination'=>['current_page'=>$page,'per_page'=>$limit,'total_items'=>$total,'total_pages'=>(int)ceil($total/$limit)]],'Requests loaded.'); } catch(Throwable $e){Logger::error('Friend requests failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to load requests.');}
?>
